private final RateService service;
private final History history;

public RateController(RateService service, History history) {
    this.service = service;
    this.history = history;
}

/** The rates on the sheet; as of a day when one is given, as they stood at the end of it (see
 *  {@link History}); then the rates of its ancestors, nearest first, likewise as of that day when
 *  one is given (a grade with no rate in force on a date on the sheet takes theirs). */
@GetMapping
public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
        @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
        LocalDate asOf) {
    History.SheetAsOf then = asOf != null ? history.asOf(sheetId.trim(), asOf) : null;
    List<Rate> rates = then != null ? then.rates() : service.list(sheetId.trim());
    Function<Rate, List<Rate>> older = then != null ? then.basis()::olderVersions : service::olderVersions;
    List<RateView> views = new ArrayList<>(rates.stream().map(r -> RateView.of(r, older.apply(r))).toList());
    List<List<Rate>> inherited = then != null ? then.inherited() : service.inherited(sheetId.trim());
    for (int i = 0; i < inherited.size(); i++) {
        int level = i + 1;
        inherited.get(i).forEach(rate -> views.add(RateView.of(rate, level, older.apply(rate))));
    }
    return views;
}

/** What the screen shows of a rate preview: the count and the sum of the differences as text with
 *  two decimals. */
public record PreviewView(int count, String diff) {
}

/** Preview a candidate rate for a grade (see {@link RateService#preview}); nothing is saved. */
@GetMapping("/{grade}/preview")
public PreviewView preview(@PathVariable @NotBlank @Size(max = 100) String sheetId,
/** The older versions of a rate, the newest first, detached. */
@Transactional(readOnly = true)
public List<Rate> olderVersions(Rate rate) {
    return versions.findByRateIdOrderByVersionDesc(rate.getId()).stream().map(v -> v.toRate(rate)).toList();
}

/** The rates set on each of the sheet's ancestors, nearest first (its parent's, then the
 *  parent's parent's, up to three levels up), each by grade and then from-date. */
@Transactional(readOnly = true)
public List<List<Rate>> inherited(String sheetId) {
    return sheets.ancestors(sheetId).stream().map(rates::findBySheetIdOrdered).toList();
}

/** Set the rate for a grade from a date (null: from the beginning of time) through a date
 *  (null: no end). When the grade has one for that from-date already, its value is kept as an
 *  older version and the new one becomes the newest version, the one in force. Saved with a
 *  from-date on or after the sheet's today, it is forward-only: it applies only to claims added
 *  after it, the claims already on the sheet keeping the rates that applied to them. */
@Transactional
public synchronized Rate set(String sheetId, String user, String grade, BigDecimal pct, LocalDate from,
        LocalDate to) {
    sheets.load(sheetId, user);
    return rollup.tracking(sheetId, user, () -> {
        Rate rate = (from == null
                ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from))
                .map(existing -> {
                    versions.save(new RateVersion(existing));
                    existing.nextVersion();
                    return existing;
                })
                .orElseGet(() -> new Rate(sheetId, grade, pct, from));
        rate.setPct(pct);
        rate.setToDate(to);
        boolean forwardOnly = from != null && !from.isBefore(sheets.today(sheetId));
        rate.setForwardAfter(forwardOnly ? claims.nextAdded() : null);
        Rate saved = rates.saveAndFlush(rate);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                + " rate=" + saved.getPct().setScale(2).toPlainString()
                + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));

